  "Внизу что-то приписано ручкой": "Abajo hay algo escrito a mano",
  "ПЕРЕМОТАЙ ЗАПИСЬ": "REBOBINA LA GRABACIÓN",
  "Тяни ползунок влево. Найди момент, когда он ещё жив.": "Arrastra la barra a la izquierda. Encuentra el momento en que aún estaba vivo.",
  "03:00:00. Он ещё жив…": "03:00:00. Aún está vivo…",
  "Свет на седьмом горит. Уборщик пропал.": "El séptimo piso está iluminado. El de la limpieza desapareció.",
  "Подняться и найти его": "Subir a buscarlo",
  "Остаться у мониторов": "Quedarse en los monitores",
  "Лифт ждёт. Табло: 13.": "El ascensor espera. Indicador: 13.",
  "Зайти внутрь": "Entrar",
  "Считать дальше": "Seguir contando",
  "ВЫДЕРНИ ШНУР": "ARRANCA EL CABLE",
  "Тяни шнур монитора вниз и держи три секунды.": "Arrastra el cable del monitor hacia abajo y mantenlo tres segundos.",
  "КТО ТАМ?": "¿QUIÉN ESTÁ AHÍ?",
  "Стекло запотело. Протри его пальцем.": "El vidrio está empañado. Límpialo con el dedo.",
  "Катя": "Katya",
  "Не спится. Ты уже на смене? Я дома, позвони утром.": "No puedo dormir. ¿Ya estás en el turno? Estoy en casa, llámame por la mañana.",
  "Ключ в замке.": "La llave está en la cerradura.",
  "Повернуть ключ": "Girar la llave",
  "Отойти от двери": "Apartarse de la puerta",
  "Лифт едет вниз.": "El ascensor está bajando.",
  "В будку, под стойку": "A la caseta, bajo el mostrador",
  "К аварийному выходу": "A la salida de emergencia",
  "Ты чего не отвечаешь? Перезвони.": "¿Por qué no contestas? Llámame.",
  "НЕ ДЫШИ": "NO RESPIRES",
  "Держи кнопку, пока шаги не уйдут. Отпустишь раньше — услышит.": "Mantén el botón hasta que se alejen los pasos. Si lo sueltas antes, te oirá.",
  "СМЕНА ОКОНЧЕНА": "FIN DEL TURNO",
  "«Ты внутри», — сказал ты ей. И не соврал.": "«Ya estás dentro», le dijiste. Y no mentías.",
  "БЕГИ": "CORRE",
  "ТЫ ВЫБРАЛСЯ": "LOGRASTE SALIR",
  "Ей правил никто не давал.": "A ella nadie le dio las reglas.",
  "«ПОМОГИ. МИНУС 2.\nСТУЧИ ТРИЖДЫ»": "«AYUDA. SÓTANO 2.\nGOLPEA TRES VECES»",
  "Минус второй. Стучать трижды.": "Sótano dos. Golpear tres veces.",
  "Спуститься": "Bajar",
  "Остаться на посту": "Quedarse en el puesto",
  "ФОНАРИК": "LINTERNA",
  "Веди пальцем, чтобы светить. В конце коридора что-то шуршит.": "Desliza el dedo para alumbrar. Al fondo del pasillo, algo se mueve.",
  "Никого. Дверь серверной — там же, в конце.": "Nadie. La puerta de la sala de servidores también está al fondo.",
  "СЕРВЕРНАЯ −2": "SERVIDORES −2",
  "«Заходи, открыто».": "«Pasa, está abierto».",
  "Толкнуть дверь": "Empujar la puerta",
  "Постучать трижды": "Golpear tres veces",
  "За дверью зашлёпали мокрые шаги. А потом заплакала Катя.": "Tras la puerta chapotearon pasos mojados. Y luego Katya se echó a llorar.",
  "ДЕРЖИ ДВЕРЬ": "AGUANTA LA PUERTA",
  "Жми чаще. До шести он будет ломиться в дверь.": "Toca más rápido. Hasta las seis intentará echar la puerta abajo.",
  "ТЫ ДОЖИЛ ДО УТРА": "SOBREVIVISTE A LA NOCHE",
  "Михалыч ушёл и не вернулся. Ты вернулся. А тот, у лифта, каждую ночь стоит чуть ближе.": "Mikhalych se fue y no volvió. Tú volviste. Y lo que espera junto al ascensor está un poco más cerca cada noche.",
  "Звонит «Катя».": "Llama «Katya».",
  "Ответить": "Contestar",
  "Сбросить": "Rechazar",
  "5. НЕ ИЩИ МИХАЛЫЧА": "5. NO BUSQUES A MIKHALYCH",
  "ПРАВИЛА СОБЛЮДЕНЫ": "REGLAS CUMPLIDAS",
  "Михалыч остался внизу. А правила теперь пишешь ты.": "Mikhalych se quedó abajo. Y ahora las reglas las escribes tú.",
  "ПРАВИЛО 1 НАРУШЕНО": "REGLA 1 ROTA",
  "В 03:00 на седьмом включится свет. Не поднимайся.": "A las 3:00 se encenderá la luz del séptimo. No subas.",
  "ПРАВИЛО 2 НАРУШЕНО": "REGLA 2 ROTA",
  "Если лифт приехал сам — не заходи.": "Si el ascensor llega solo, no entres.",
  "Я включил тринадцатую. Он уже смотрел в камеру. Ждал.": "Encendí la trece. Ya estaba mirando a la cámara. Esperando.",
  "ПРАВИЛО 4 НАРУШЕНО": "REGLA 4 ROTA",
  "Камеру 13 не включай.": "No enciendas la cámara 13.",
  "ОНО ТЕБЯ УВИДЕЛО": "ESO TE VIO",
  "Если тринадцатая включилась сама — выдёргивай шнур.": "Si la trece se enciende sola, arranca el cable.",
  "ОНО УСЛЫШАЛО ТЕБЯ": "ESO TE OYÓ",
  "Пока шаги рядом — не дыши.": "Mientras los pasos estén cerca, no respires.",
  "ТЕМНОТА ДОГНАЛА": "LA OSCURIDAD TE ALCANZÓ",
  "Не оглядывайся. Беги туда, где ещё светло.": "No mires atrás. Corre hacia donde aún hay luz.",
  "ЗА ДВЕРЬЮ БЫЛО ОНО": "TRAS LA PUERTA ESTABA ESO",
  "Он умеет звать. Стучать — нет.": "Sabe llamarte por tu nombre. Golpear, no.",
  "ЗАСОВ НЕ ВЫДЕРЖАЛ": "EL CERROJO CEDIÓ",
  "Держи дверь до рассвета. Не сбавляй.": "Aguanta la puerta hasta el amanecer. No aflojes.",
  "ТЫ ОТВЕТИЛ": "CONTESTASTE",
  "Ответить — значит впустить.": "Contestar es dejarlo entrar.",
  "Пусто. Дождь стеной. На стекле чей-то отпечаток ладони?.. Нет, просто капли.": "Vacío. Llueve a cántaros. ¿Una huella de mano en el vidrio…? No, solo gotas.",
  "У лифта кто-то стоит?.. Нет. Показалось.": "¿Hay alguien junto al ascensor…? No. Fue mi imaginación.",
  "Уборщик домывает седьмой. Хоть кто-то живой в этом здании.": "El de la limpieza termina el séptimo. Al menos hay alguien vivo en este edificio.",
