  "Нажми камеру 03 — лифты": "Toca la cámara 03: ascensores",
  "Смотри на табло лифта: «13»": "Mira el indicador del ascensor: «13»",
  "Нажми «Записать» → «Лифт»": "Toca «Anotar» → «Ascensor»",
  "MIC слева вверху: столбики прыгают — звук": "MIC arriba a la izquierda: si saltan las barras, hay sonido",
  "Открой «Пульт»": "Abre el «Panel»",
  "Открой «Журнал»": "Abre la «Bitácora»",
  "Камеры — кнопки внизу. Переключай и запоминай, как там обычно.": "Las cámaras son los botones de abajo. Cambia entre ellas y recuerda cómo se ven normalmente.",
  "Заметил, что не так, — «Записать» и выбери, что это: свет, дверь, лифт, помехи, кто-то, звук, другое.": "¿Notas algo raro? Toca «Anotar» y elige qué es: luz, puerta, ascensor, estática, alguien, sonido, otro.",
  "MIC слева вверху: прыгают столбики — на этой камере звук.": "MIC arriba a la izquierda: si saltan las barras, hay sonido en esa cámara.",
  "«Пульт»: свет на этажах, вход, лифт. Лишний свет — выключи. К 22:00 вход запри, лифт останови.": "«Panel»: luces de los pisos, entrada, ascensor. Apaga las luces de sobra. Antes de las 22:00, cierra la entrada y detén el ascensor.",
  "Три пропущенные странности за час — оно придёт к будке.": "Tres anomalías sin anotar en una hora y eso vendrá a la caseta.",
  "Помехи на камере — не засматривайся: записал и переключил.": "Estática en una cámara: no te quedes mirando. Anota y cambia.",
  "Не отзывайся, если зовут по имени. Не открывай дверь.": "No respondas si te llaman por tu nombre. No abras la puerta.",
  "В эфире": "Por la radio",
  "Графика «Кино» на этом устройстве рисовала слишком темно — включена «Ретро». Вернуть: Настройки → Графика.": "Los gráficos «Cine» se veían demasiado oscuros en este dispositivo, así que se activó «Retro». Para volver: Opciones → Gráficos.",
  "Поддержать игру": "Apoyar el juego",
  "Полная версия — {p}": "Juego completo — {p}",
  "ОТКРОЕШЬ ЕЙ?": "¿LE ABRIRÁS?",
  "Здесь кончается бесплатная часть — у стеклянной двери, в 03:30.": "Aquí termina la parte gratuita: en la puerta de vidrio, a las 3:30.",
  "В полной версии ночь идёт до шести: что будет, если открыть — и если нет, подвал, ещё два часа смены, четыре концовки.": "En el juego completo, la noche sigue hasta las seis: qué pasa si abres y si no, el sótano, dos horas más de turno, cuatro finales.",
  "Полная версия скачивается на странице игры и работает без интернета.": "El juego completo se descarga en la página del juego y funciona sin conexión.",
