  "CAM 00  БУДКА": "CAM 00  CASETA",
  "Удачи на первой смене! Не засни там :)": "¡Suerte en tu primer turno! No te duermas :)",
  "Сменщик протягивает связку. Рука дрожит.": "El otro vigilante te tiende el manojo de llaves. Le tiembla la mano.",
  "«Как это — не сдал?»": "«¿Cómo que no lo entregó?»",
  "ЖУРНАЛ ФРЭНКА": "LA BITÁCORA DE FRANK",
  "НЕ ОТЗЫВАЙСЯ НА ИМЯ.\nНЕ ОТКРЫВАЙ ЕМУ ДВЕРЬ.\nСАМ К НЕМУ НЕ ХОДИ —\nНИ НА СВЕТ, НИ В ЛИФТ.": "NO RESPONDAS A TU NOMBRE.\nNO LE ABRAS LA PUERTA.\nNO TE ACERQUES TÚ —\nNI A LA LUZ, NI AL ASCENSOR.",
  "МАМА ПОЗВАЛА. Я ОТВЕТИЛ.\nСОЛЬ ДЕРЖИТ. ИДУ ВНИЗ.": "MAMÁ ME LLAMÓ. RESPONDÍ.\nLA SAL LO FRENA. VOY ABAJO.",
  "Тяни ползунок влево. Найди, где он ещё здесь.": "Arrastra la barra a la izquierda. Busca cuándo aún estaba ahí.",
  "03:00:00. Гас стоит у двери 707…": "03:00:00. Gus está junto a la puerta 707…",
  "Полиция": "Policía",
  "На седьмом горит свет. Гаса нет.": "Hay luz en el séptimo. Gus no está.",
  "Подняться на седьмой": "Subir al séptimo",
  "Остаться в будке": "Quedarse en la caseta",
  "Рация зовёт тебя по имени.": "La radio te llama por tu nombre.",
  "Ответить: «Гас, держись!»": "Responder: «¡Aguanta, Gus!»",
  "Выключить рацию": "Apagar la radio",
  "Оно оборачивается. Тяни вилку вниз!": "Eso se da la vuelta. ¡Arrastra el enchufe hacia abajo!",
  "Не спится :( Как первая смена? Позвони утром": "No puedo dormir :( ¿Qué tal el primer turno? Llámame por la mañana",
  "минуту назад": "hace un minuto",
  "«Итан, открой!»": "«¡Ethan, ábreme!»",
  "Открыть": "Abrir",
  "Написать на стекле": "Escribir en el vidrio",
  "Оно повторяет твоё имя.": "Eso repite tu nombre.",
  "Спрятаться в будке": "Esconderse en la caseta",
  "Бежать к аварийному выходу": "Correr a la salida de emergencia",
  "Оно ищет на звук. Держи палец, пока шаги рядом.": "Eso busca por el sonido. Mantén el dedo mientras los pasos estén cerca.",
  "ВНУТРИ": "DENTRO",
  "«Ты со мной», — сказал ты ей. И не соврал.": "«Estás conmigo», le dijiste. Y no mentías.",
  "СЕСТРА": "HERMANA",
  "Оно пошло туда, где его ещё не ждут. Твоим голосом.": "Eso se fue adonde aún nadie lo espera. Con tu voz.",
  "CAM −2  СЕРВЕРНАЯ": "CAM −2  SERVIDORES",
  "CAM −2  ПОДВАЛ": "CAM −2  SÓTANO",
  "НЕ ЗОВИ МЕНЯ.\nСТУЧИ ТРИ РАЗА.": "NO ME LLAMES.\nGOLPEA TRES VECES.",
  "Фрэнк жив. Он внизу.": "Frank está vivo. Está abajo.",
  "Спуститься к нему": "Bajar a buscarlo",
  "ПОДВАЛ": "SÓTANO",
  "Темно. Веди фонарём, найди дверь серверной.": "Está oscuro. Mueve la linterna y encuentra la puerta de la sala de servidores.",
  "Железная дверь. Под ней — свет.": "Una puerta de hierro. Debajo, luz.",
  "«Заходи, сынок. Открыто».": "«Pasa, hijo. Está abierto».",
  "Открыть дверь": "Abrir la puerta",
  "Постучать три раза": "Golpear tres veces",
  "ДЕРЖИ ФРЭНКА": "SUJETA A FRANK",
  "Мать зовёт его из темноты. Не отпускай, пока голос не стихнет.": "Su madre lo llama desde la oscuridad. No lo sueltes hasta que la voz se apague.",
  "силы": "fuerzas",
  "ДЕРЖАТЬ": "SUJETAR",
  "ДЕРЖУ": "SUJETANDO",
  "Голос стих. Ненадолго.": "La voz se apagó. Por ahora.",
  "CAM 04  ЛЕСТНИЦА": "CAM 04  ESCALERA",
  "CAM 02  ХОЛЛ  03:00": "CAM 02  VESTÍBULO  03:00",
  "РАССВЕТ": "AMANECER",
  "Ты ни разу не ответил. Пока.": "No respondiste ni una vez. Por ahora.",
  "Звонит «Лили».": "Llama «Lily».",
  "ТЫ НЕ СПУСТИЛСЯ": "NO BAJASTE",
  "Ты дожил до утра. Фрэнк — нет.": "Llegaste a la mañana. Frank, no.",
  "ТЫ ПОСМОТРЕЛ ЕМУ В ЛИЦО": "LO MIRASTE A LA CARA",
  "Не смотри в тринадцатую камеру.": "No mires la cámara trece.",
  "ТЫ ПОШЁЛ НА СВЕТ": "FUISTE HACIA LA LUZ",
  "Сам к нему не ходи — ни на свет, ни в лифт.": "No te acerques tú: ni a la luz, ni al ascensor.",
  "ТЫ ОТОЗВАЛСЯ": "RESPONDISTE",
  "Гас не знал твоего имени. А оно знает.": "Gus no sabía tu nombre. Eso sí lo sabe.",
  "ОНО ОБЕРНУЛОСЬ": "ESO SE DIO LA VUELTA",
  "Тринадцатая включилась сама — выдёргивай шнур, не смотри.": "La trece se encendió sola: arranca el cable y no mires.",
  "ОНО УСЛЫШАЛО": "ESO TE OYÓ",
  "Оно ищет на звук. Пока шаги рядом — не дыши.": "Eso busca por el sonido. Mientras los pasos estén cerca, no respires.",
  "Остановишься — догонит.": "Si te detienes, te alcanza.",
  "ТЫ ПОШЁЛ НА ЗОВ": "ACUDISTE A LA LLAMADA",
  "Оно умеет звать. Стучать — нет.": "Eso sabe llamar. Golpear, no.",
  "ФРЭНК УШЁЛ НА ГОЛОС": "FRANK FUE HACIA LA VOZ",
  "Держи его, пока голос не стихнет.": "Sujétalo hasta que la voz se apague.",
  "Свои до утра подождут.": "Los tuyos esperarán hasta la mañana.",
  "ОБХОД": "LA RONDA",
  "СЕДЬМОЙ ЭТАЖ": "SÉPTIMO PISO",
  "ТЫ ОТКРЫЛ ЕЙ": "LE ABRISTE",
  "Лили спала в трёхстах километрах отсюда. Посторонних не впускать.": "Lily dormía a trescientos kilómetros de aquí. No dejar entrar a extraños.",
  "ОНО ПРИШЛО": "ESO LLEGÓ",
  "Три странности за час остались без внимания. Смотри камеры, записывай, выключай лишний свет.": "Tres anomalías en una hora sin anotar. Mira las cámaras, anota lo que veas, apaga las luces de sobra.",
  "ТЫ ЗАСМОТРЕЛСЯ": "MIRASTE DEMASIADO",
  "Там, где помехи, кто-то стоит. Не смотри — запиши и переключи.": "Donde hay estática, hay alguien. No mires: anota y cambia.",
  "Внутренний": "Línea interna",
  "ТЫ НАЗВАЛСЯ": "DIJISTE TU NOMBRE",
  "Оно знает твоё имя. Ему нужно только, чтобы ты ответил.": "Eso ya sabe tu nombre. Solo necesita que respondas.",
  "Новая запись": "Nueva anotación",
