  "Пока ни одной записи.": "Nenhuma anotação ainda.",
  "Фрэнк поднимается на голос. Не отпускай, пока голос не стихнет.": "O Frank está indo atrás da voz. Não solte até ela se calar.",
  "Голос стих. Фрэнк сел на пол и закрыл лицо руками.": "A voz se calou. O Frank sentou no chão e cobriu o rosto com as mãos.",
  "Звонит внутренний телефон": "O interfone está tocando",
