  "БУБЛИК": "BISCOITO",
  "03.10  Обход. Лампа на 4-м мигает.": "03/10  Ronda. Luz do 4º piscando.",
  "05.10  Обход. Кошка у баков.": "05/10  Ronda. Gata nas lixeiras.",
  "08.10  Обход. Без происшествий.": "08/10  Ronda. Sem ocorrências.",
  "10.10  Обход. Без происшествий.": "10/10  Ronda. Sem ocorrências.",
