  "       Соль держит. Иду вниз.": "       O sal protege. Vou descer.",
  "28.10  ФРЭНК БЫЛ ЖИВ.": "28/10  FRANK ESTAVA VIVO.",
  "       Я НЕ СПУСТИЛСЯ.  — И.": "       EU NÃO DESCI.  — E.",
  "ЖУРНАЛ НОЧНЫХ СМЕН": "DIÁRIO DE PLANTÃO",
  "СЕРВЕРНАЯ": "SERVIDORES",
  "Как звали": "Nome do",
  "собаку?": "cão?",
  "НЕ ЗОВИ МЕНЯ.": "NÃO ME CHAME.",
  "СТУЧИ ТРИ РАЗА": "BATA 3 VEZES",
  "ПАМЯТКА ОХРАННИКУ БЦ «ГОРИЗОНТ»": "INSTRUÇÕES AO VIGIA · CENTRO EMPRESARIAL HORIZON",
  "22:00 — запереть вход, лифт — в ночной режим (СТОП).": "22h — trancar a entrada; elevador em modo noturno (PARADO).",
  "Каждый час — осмотр по камерам. Замечания — в журнал (кнопка «Записать»).": "De hora em hora, ronda pelas câmeras. Ocorrências no diário (botão “Anotar”).",
  "Свет на пустых этажах — выключать с пульта.": "Luz acesa em andar vazio: apagar pelo painel.",
  "Посторонних не впускать.": "Proibida a entrada de estranhos.",
  "Внутренний телефон — для связи с охраной соседних зданий.": "O interfone serve para falar com a segurança dos prédios vizinhos.",
  "(на обороте обложки, карандашом) Помехи на камере — не засматривайся. Запиши и переключи.": "(no verso da capa, a lápis) Estática na câmera: não fique olhando. Anote e troque.",
  "12.10  Лифт ночью ездит сам. Техник: «датчик».": "12/10  O elevador anda sozinho à noite. Técnico: “sensor”.",
  "15.10  Гаса зовут с 7-го. По имени. Голосом Марты. Марта три года как умерла.": "15/10  Chamam o Gus do 7º. Pelo nome. Com a voz da Martha. A Martha morreu faz três anos.",
  "18.10  На пульте CAM 13. Такой камеры нет. Не смотри.": "18/10  CAM 13 no painel. Essa câmera não existe. Não olhe.",
  "20.10  НЕ ОТЗЫВАЙСЯ НА ИМЯ. НЕ ОТКРЫВАЙ ЕМУ ДВЕРЬ. САМ К НЕМУ НЕ ХОДИ — НИ НА СВЕТ, НИ В ЛИФТ.": "20/10  NÃO RESPONDA SE CHAMAREM SEU NOME. NÃO ABRA A PORTA PRA AQUILO. NÃO VÁ ATÉ AQUILO — NEM PRA LUZ, NEM PRO ELEVADOR.",
  "21.10  Мама позвала. Я ответил. Соль держит. Иду вниз.": "21/10  Mamãe chamou. Eu respondi. O sal protege. Vou descer.",
  "Пульт пискнул: «ВХОД — ОТКРЫТ».": "O painel apitou: “ENTRADA — ABERTA”.",
  "Камеры — внизу. Странное — «Записать». Свет, вход и лифт — на пульте.": "Câmeras embaixo. Algo estranho? “Anotar”. Luz, entrada e elevador ficam no painel.",
  "К 22:00 запереть вход и остановить лифт": "Até as 22h, trancar a entrada e parar o elevador",
  "Ты как там? Не страшно одному? 😄": "E aí? Não tá com medo sozinho? 😄",
  "Нормально. Спи давай.": "Tô de boa. Vai dormir.",
  "Если честно — жутковато.": "Sinceramente? Tá meio sinistro.",
  "Держись! Утром позвоню": "Aguenta firme! Te ligo de manhã",
  "«Итан?.. Это ты?»": "“Ethan?… É você?”",
  "— Да. Это я.": "— Sim. Sou eu.",
  "Молча положить трубку": "Desligar sem dizer nada",
  "Рация. Канал уборщика": "Rádio. Canal do faxineiro",
  "Сквозь шипение — голос Гаса.": "No meio do chiado, a voz do Gus.",
  "Не отвечать": "Não responder",
  "«Итан… Спустись ко мне»": "“Ethan… Desce aqui comigo”",
  "— Гас! Держись, я сейчас поднимусь!": "— Gus! Aguenta aí, tô subindo!",
  "Итан, я внизу у входа. Открой, пожалуйста, я промокла насквозь": "Ethan, tô lá embaixo na entrada. Abre, por favor, tô encharcada",
  "Ты прячешься. Смотри камеры и записывай. Шаги у будки — «НЕ ДЫШИ».": "Você está escondido. Vigie as câmeras e anote. Passos perto da guarita? “NÃO RESPIRE”.",
  "Шаги у самой будки. Держи кнопку, пока она не уйдёт.": "Passos colados na guarita. Segure o botão até ela ir embora.",
  "Она дышит за стеклом будки. Не отпускай.": "Ela está respirando do outro lado do vidro da guarita. Não solte.",
  "ЗАТАИТЬСЯ": "FIQUE QUIETO",
  "НЕ ДЫШУ": "SEM RESPIRAR",
  "Шаги удаляются. Пока.": "Os passos se afastam. Por enquanto.",
  "Я на седьмом. Тут светло и тепло. Поднимись ко мне?": "Tô no sétimo. Aqui tá claro e quentinho. Sobe aqui?",
  "БУДКА ФРЭНКА": "A GUARITA DO FRANK",
  "ЗВОНОК": "A LIGAÇÃO",
  "Осмотрись. Нажми на то, что хочешь проверить.": "Olhe ao redor. Toque no que quiser examinar.",
  "Осмотри будку. Нажми на то, что хочешь проверить.": "Examine a guarita. Toque no que quiser ver.",
  "Куртка Фрэнка": "Jaqueta do Frank",
  "Фото под стеклом": "Foto sob o vidro",
  "Ящик стола": "Gaveta da mesa",
  "Сесть за мониторы": "Sentar nos monitores",
  "Марта.\nСедьмой этаж.\nНовый год": "Martha.\nSétimo andar.\nAno Novo",
  "Дневной охранник": "Vigia do dia",
  "Что на самом деле случилось с Фрэнком?": "O que houve de verdade com o Frank?",
  "Зачем ты стучал в стекло?": "Por que você bateu no vidro?",
  "«Оно» — это кто?": "O que é “aquilo”?",
  "В здании ещё кто-нибудь есть?": "Tem mais alguém no prédio?",
  "«Ладно. До утра»": "“Beleza. Até de manhã”",
