  "Спасибо. А вы давно тут?": "Obrigado. O senhor tá aqui faz tempo?",
  "Женщина на фото у Фрэнка — это Марта?": "A mulher na foto do Frank é a Martha?",
  "Ваша жена тоже здесь работала?": "Sua esposa também trabalhava aqui?",
  "Фрэнк что-нибудь говорил перед тем, как пропасть?": "O Frank disse alguma coisa antes de sumir?",
  "Кто вас зовёт?": "Quem chama o senhor?",
  "«Что бы она ни говорила — не отвечайте»": "“O que quer que ela diga, não responda”",
  "Пора в будку": "Hora de voltar pra guarita",
  "Как там Бублик?": "Como tá o Biscoito?",
  "Ты сейчас в общаге?": "Você tá no alojamento agora?",
  "Тут… странно": "Aqui tá… estranho",
  "«Спи давай. Всё сдашь»": "“Vai dormir. Você vai arrasar”",
  "Всё ещё не сплю :( Ты как там? Утром позвони!": "Ainda sem sono :( Como você tá? Me liga de manhã!",
