  "Фрэнки, сынок, спустись ко мне. Я внизу": "Frankie, filho, desce aqui. Tô aqui embaixo",
  "На зарядке. Номер не определён.": "No carregador. Número desconhecido.",
  "Ответить: «Алло?»": "Atender: “Alô?”",
