  "БЦ «ГОРИЗОНТ» · 02:55": "BÜROZENTRUM HORIZON · 02:55",
  "Нажми, чтобы заступить на смену": "Tippen zum Schichtbeginn",
  "Сменщик протягивает ключи. Рука дрожит.": "Der Kollege hält dir die Schlüssel hin. Seine Hand zittert.",
  "Взять ключи": "Schlüssel nehmen",
  "«А почему втрое?»": "„Warum dreifach?“",
  "Нажми на листок, чтобы прочитать": "Tippe auf den Zettel",
  "1. В 03:00 НА 7 ЭТАЖЕ\nВКЛЮЧИТСЯ СВЕТ.\nНЕ ПОДНИМАЙСЯ": "1. UM 3:00 GEHT IM 7. STOCK\nDAS LICHT AN.\nNICHT HOCHGEHEN",
  "2. ЛИФТ ПРИЕХАЛ САМ —\nНЕ ЗАХОДИ": "2. KOMMT DER AUFZUG VON SELBST —\nNICHT EINSTEIGEN",
  "3. ПОСЛЕ ПОЛУНОЧИ\nНИКОГО НЕ ВПУСКАЙ.\nДАЖЕ СВОИХ": "3. NACH MITTERNACHT\nNIEMANDEN EINLASSEN.\nAUCH NICHT DIE DEINEN",
  "4. КАМЕРУ 13\nНЕ ВКЛЮЧАЙ": "4. KAMERA 13\nNICHT EINSCHALTEN",
  "«ТРЕТЬЕ ПРАВИЛО — ЛОЖЬ.\nВПУСТИ ЕЁ.»  — М.": "„REGEL DREI IST GELOGEN.\nLASS SIE REIN.“  — M.",
  "Внизу что-то приписано ручкой": "Unten ist etwas hingekritzelt",
  "ПЕРЕМОТАЙ ЗАПИСЬ": "ZURÜCKSPULEN",
  "Тяни ползунок влево. Найди момент, когда он ещё жив.": "Zieh den Regler nach links. Finde den Moment, als er noch lebte.",
  "03:00:00. Он ещё жив…": "03:00:00. Er lebt noch…",
  "Свет на седьмом горит. Уборщик пропал.": "Im Siebten brennt Licht. Der Putzmann ist verschwunden.",
  "Подняться и найти его": "Hochgehen und ihn suchen",
  "Остаться у мониторов": "An den Monitoren bleiben",
  "Лифт ждёт. Табло: 13.": "Der Aufzug wartet. Anzeige: 13.",
  "Зайти внутрь": "Einsteigen",
  "Считать дальше": "Weiterzählen",
  "ВЫДЕРНИ ШНУР": "ZIEH DEN STECKER",
  "Тяни шнур монитора вниз и держи три секунды.": "Zieh das Monitorkabel nach unten und halte es drei Sekunden.",
  "КТО ТАМ?": "WER IST DA?",
  "Стекло запотело. Протри его пальцем.": "Das Glas ist beschlagen. Wisch es mit dem Finger frei.",
  "Катя": "Katja",
  "Не спится. Ты уже на смене? Я дома, позвони утром.": "Kann nicht schlafen. Bist du schon auf Schicht? Ich bin zu Hause, ruf morgen früh an.",
  "Ключ в замке.": "Der Schlüssel steckt im Schloss.",
  "Повернуть ключ": "Schlüssel drehen",
  "Отойти от двери": "Von der Tür zurücktreten",
  "Лифт едет вниз.": "Der Aufzug fährt nach unten.",
  "В будку, под стойку": "In die Kabine, unter den Tresen",
  "К аварийному выходу": "Zum Notausgang",
  "Ты чего не отвечаешь? Перезвони.": "Warum gehst du nicht ran? Ruf zurück.",
  "НЕ ДЫШИ": "NICHT ATMEN",
  "Держи кнопку, пока шаги не уйдут. Отпустишь раньше — услышит.": "Halte die Taste, bis die Schritte weg sind. Lässt du zu früh los, hört es dich.",
  "СМЕНА ОКОНЧЕНА": "SCHICHT VORBEI",
  "«Ты внутри», — сказал ты ей. И не соврал.": "„Du bist drinnen“, hast du ihr gesagt. Und nicht gelogen.",
  "БЕГИ": "LAUF",
  "ТЫ ВЫБРАЛСЯ": "DU BIST ENTKOMMEN",
  "Ей правил никто не давал.": "Ihr hat niemand die Regeln gegeben.",
  "«ПОМОГИ. МИНУС 2.\nСТУЧИ ТРИЖДЫ»": "„HILFE. MINUS 2.\nKLOPF DREIMAL“",
  "Минус второй. Стучать трижды.": "Minus zwei. Dreimal klopfen.",
  "Спуститься": "Runtergehen",
  "Остаться на посту": "Auf dem Posten bleiben",
  "ФОНАРИК": "TASCHENLAMPE",
  "Веди пальцем, чтобы светить. В конце коридора что-то шуршит.": "Führ den Finger, um zu leuchten. Am Ende des Flurs raschelt etwas.",
  "Никого. Дверь серверной — там же, в конце.": "Niemand. Die Tür zum Serverraum ist auch dort, am Ende.",
  "СЕРВЕРНАЯ −2": "SERVERRAUM −2",
  "«Заходи, открыто».": "„Komm rein, ist offen.“",
  "Толкнуть дверь": "Tür aufdrücken",
  "Постучать трижды": "Dreimal klopfen",
  "За дверью зашлёпали мокрые шаги. А потом заплакала Катя.": "Hinter der Tür patschten nasse Schritte. Dann fing Katja an zu weinen.",
  "ДЕРЖИ ДВЕРЬ": "HALT DIE TÜR",
  "Жми чаще. До шести он будет ломиться в дверь.": "Tippe schneller. Bis sechs wird es gegen die Tür hämmern.",
  "ТЫ ДОЖИЛ ДО УТРА": "DU HAST DIE NACHT ÜBERLEBT",
  "Михалыч ушёл и не вернулся. Ты вернулся. А тот, у лифта, каждую ночь стоит чуть ближе.": "Michalytsch ging und kam nicht wieder. Du bist wiedergekommen. Und das Ding am Aufzug steht jede Nacht ein Stück näher.",
  "Звонит «Катя».": "„Katja“ ruft an.",
  "Ответить": "Antworten",
  "Сбросить": "Ablehnen",
  "5. НЕ ИЩИ МИХАЛЫЧА": "5. SUCH NICHT NACH MICHALYTSCH",
  "ПРАВИЛА СОБЛЮДЕНЫ": "REGELN BEFOLGT",
  "Михалыч остался внизу. А правила теперь пишешь ты.": "Michalytsch blieb unten. Und die Regeln schreibst jetzt du.",
  "ПРАВИЛО 1 НАРУШЕНО": "REGEL 1 GEBROCHEN",
  "В 03:00 на седьмом включится свет. Не поднимайся.": "Um 3:00 geht im Siebten das Licht an. Geh nicht hoch.",
  "ПРАВИЛО 2 НАРУШЕНО": "REGEL 2 GEBROCHEN",
  "Если лифт приехал сам — не заходи.": "Kommt der Aufzug von selbst — steig nicht ein.",
  "Я включил тринадцатую. Он уже смотрел в камеру. Ждал.": "Ich schaltete die Dreizehn ein. Es sah schon in die Kamera. Wartete.",
  "ПРАВИЛО 4 НАРУШЕНО": "REGEL 4 GEBROCHEN",
  "Камеру 13 не включай.": "Schalte Kamera 13 nicht ein.",
  "ОНО ТЕБЯ УВИДЕЛО": "ES HAT DICH GESEHEN",
  "Если тринадцатая включилась сама — выдёргивай шнур.": "Geht die Dreizehn von selbst an — zieh den Stecker.",
  "ОНО УСЛЫШАЛО ТЕБЯ": "ES HAT DICH GEHÖRT",
  "Пока шаги рядом — не дыши.": "Solange die Schritte nah sind — nicht atmen.",
  "ТЕМНОТА ДОГНАЛА": "DIE DUNKELHEIT WAR SCHNELLER",
  "Не оглядывайся. Беги туда, где ещё светло.": "Dreh dich nicht um. Lauf dahin, wo es noch hell ist.",
  "ЗА ДВЕРЬЮ БЫЛО ОНО": "HINTER DER TÜR WAR ES",
  "Он умеет звать. Стучать — нет.": "Es kann rufen. Klopfen kann es nicht.",
  "ЗАСОВ НЕ ВЫДЕРЖАЛ": "DER RIEGEL HAT NACHGEGEBEN",
  "Держи дверь до рассвета. Не сбавляй.": "Halt die Tür bis zum Morgengrauen. Lass nicht nach.",
  "ТЫ ОТВЕТИЛ": "DU HAST GEANTWORTET",
  "Ответить — значит впустить.": "Antworten heißt hereinlassen.",
  "Пусто. Дождь стеной. На стекле чей-то отпечаток ладони?.. Нет, просто капли.": "Leer. Regen wie eine Wand. Ein Handabdruck auf dem Glas?.. Nein, nur Tropfen.",
  "У лифта кто-то стоит?.. Нет. Показалось.": "Steht da jemand am Aufzug?.. Nein. Nur Einbildung.",
  "Уборщик домывает седьмой. Хоть кто-то живой в этом здании.": "Der Putzmann wischt den Siebten fertig. Wenigstens einer lebt in diesem Gebäude.",
