  "Нажми камеру 03 — лифты": "Tippe auf Kamera 03 — die Aufzüge",
  "Смотри на табло лифта: «13»": "Sieh auf die Aufzugsanzeige: „13“",
  "Нажми «Записать» → «Лифт»": "„Eintragen“ → „Aufzug“",
  "MIC слева вверху: столбики прыгают — звук": "MIC oben links: Balken springen — ein Geräusch",
  "Открой «Пульт»": "Öffne das „Pult“",
  "Открой «Журнал»": "Öffne das „Wachbuch“",
  "Камеры — кнопки внизу. Переключай и запоминай, как там обычно.": "Die Kameras sind die Tasten unten. Schalte um und merk dir, wie es dort normal aussieht.",
  "Заметил, что не так, — «Записать» и выбери, что это: свет, дверь, лифт, помехи, кто-то, звук, другое.": "Stimmt etwas nicht? Tippe auf „Eintragen“ und wähle, was es ist: Licht, Tür, Aufzug, Rauschen, jemand, Geräusch, anderes.",
  "MIC слева вверху: прыгают столбики — на этой камере звук.": "MIC oben links: Springen die Balken, gibt es auf dieser Kamera ein Geräusch.",
  "«Пульт»: свет на этажах, вход, лифт. Лишний свет — выключи. К 22:00 вход запри, лифт останови.": "„Pult“: Licht auf den Etagen, Eingang, Aufzug. Überflüssiges Licht ausschalten. Bis 22 Uhr den Eingang abschließen und den Aufzug stoppen.",
  "Три пропущенные странности за час — оно придёт к будке.": "Drei übersehene Anomalien in einer Stunde — dann kommt es zur Kabine.",
  "Помехи на камере — не засматривайся: записал и переключил.": "Rauschen auf einer Kamera: nicht hinstarren. Eintragen und umschalten.",
  "Не отзывайся, если зовут по имени. Не открывай дверь.": "Antworte nicht, wenn dich jemand beim Namen ruft. Mach die Tür nicht auf.",
  "В эфире": "Am Funk",
  "Графика «Кино» на этом устройстве рисовала слишком темно — включена «Ретро». Вернуть: Настройки → Графика.": "„Kino“ war auf diesem Gerät zu dunkel, deshalb ist „Retro“ an. Zurück: Einstellungen → Grafik.",
  "Поддержать игру": "Spiel unterstützen",
  "Полная версия — {p}": "Vollversion — {p}",
  "ОТКРОЕШЬ ЕЙ?": "MACHST DU IHR AUF?",
  "Здесь кончается бесплатная часть — у стеклянной двери, в 03:30.": "Hier endet der kostenlose Teil: an der Glastür, um 3:30.",
  "В полной версии ночь идёт до шести: что будет, если открыть — и если нет, подвал, ещё два часа смены, четыре концовки.": "In der Vollversion geht die Nacht bis sechs: was passiert, wenn du aufmachst, und wenn nicht. Der Keller, zwei weitere Stunden Schicht, vier Enden.",
  "Полная версия скачивается на странице игры и работает без интернета.": "Die Vollversion lädst du auf der Spielseite herunter, sie läuft auch offline.",
  "СПОНСОРЫ ИГРЫ": "SPONSOREN DES SPIELS",
