  "Сменщик протягивает связку. Рука дрожит.": "Der Kollege hält dir den Schlüsselbund hin. Seine Hand zittert.",
  "«Как это — не сдал?»": "„Was heißt das, keine Übergabe?“",
  "ЖУРНАЛ ФРЭНКА": "FRANKS WACHBUCH",
  "НЕ ОТЗЫВАЙСЯ НА ИМЯ.\nНЕ ОТКРЫВАЙ ЕМУ ДВЕРЬ.\nСАМ К НЕМУ НЕ ХОДИ —\nНИ НА СВЕТ, НИ В ЛИФТ.": "ANTWORTE NICHT AUF DEINEN NAMEN.\nMACH IHM NICHT AUF.\nGEH NICHT SELBST ZU IHM —\nNICHT INS LICHT, NICHT IN DEN AUFZUG.",
  "МАМА ПОЗВАЛА. Я ОТВЕТИЛ.\nСОЛЬ ДЕРЖИТ. ИДУ ВНИЗ.": "MAMA RIEF. ICH ANTWORTETE.\nDAS SALZ HÄLT. GEHE RUNTER.",
  "Тяни ползунок влево. Найди, где он ещё здесь.": "Zieh den Regler nach links. Finde, wo er noch da ist.",
  "03:00:00. Гас стоит у двери 707…": "03:00:00. Gus steht vor Tür 707…",
  "Полиция": "Polizei",
  "На седьмом горит свет. Гаса нет.": "Im Siebten brennt Licht. Gus ist weg.",
  "Подняться на седьмой": "Hoch in den Siebten",
  "Остаться в будке": "In der Kabine bleiben",
  "Рация зовёт тебя по имени.": "Das Funkgerät ruft deinen Namen.",
  "Ответить: «Гас, держись!»": "Antworten: „Gus, halt durch!“",
  "Выключить рацию": "Funkgerät ausschalten",
  "Оно оборачивается. Тяни вилку вниз!": "Es dreht sich um. Zieh den Stecker runter!",
  "Не спится :( Как первая смена? Позвони утром": "Kann nicht schlafen :( Wie ist die erste Schicht? Ruf morgen früh an",
  "минуту назад": "vor einer Minute",
  "«Итан, открой!»": "„Ethan, mach auf!“",
  "Открыть": "Aufmachen",
  "Написать на стекле": "Aufs Glas schreiben",
  "Оно повторяет твоё имя.": "Es wiederholt deinen Namen.",
  "Спрятаться в будке": "In der Kabine verstecken",
  "Бежать к аварийному выходу": "Zum Notausgang rennen",
  "Оно ищет на звук. Держи палец, пока шаги рядом.": "Es jagt nach Gehör. Halt den Finger drauf, solange die Schritte nah sind.",
  "ВНУТРИ": "DRINNEN",
  "«Ты со мной», — сказал ты ей. И не соврал.": "„Du bist bei mir“, hast du ihr gesagt. Und nicht gelogen.",
  "СЕСТРА": "SCHWESTER",
  "Оно пошло туда, где его ещё не ждут. Твоим голосом.": "Es ging dorthin, wo man es noch nicht erwartet. Mit deiner Stimme.",
  "CAM −2  СЕРВЕРНАЯ": "CAM −2  SERVERRAUM",
  "CAM −2  ПОДВАЛ": "CAM −2  KELLER",
  "НЕ ЗОВИ МЕНЯ.\nСТУЧИ ТРИ РАЗА.": "RUF MICH NICHT.\nKLOPF DREIMAL.",
  "Фрэнк жив. Он внизу.": "Frank lebt. Er ist unten.",
  "Спуститься к нему": "Zu ihm runtergehen",
  "ПОДВАЛ": "KELLER",
  "Темно. Веди фонарём, найди дверь серверной.": "Dunkel. Leuchte mit der Lampe und finde die Tür zum Serverraum.",
  "Железная дверь. Под ней — свет.": "Eine Eisentür. Darunter — Licht.",
  "«Заходи, сынок. Открыто».": "„Komm rein, Junge. Ist auf.“",
  "Открыть дверь": "Tür öffnen",
  "Постучать три раза": "Dreimal klopfen",
  "ДЕРЖИ ФРЭНКА": "HALT FRANK FEST",
  "Мать зовёт его из темноты. Не отпускай, пока голос не стихнет.": "Seine Mutter ruft ihn aus dem Dunkel. Lass nicht los, bis die Stimme verstummt.",
  "силы": "Kraft",
