  "НЕ ЗОВИ МЕНЯ.": "RUF MICH NICHT.",
  "СТУЧИ ТРИ РАЗА": "KLOPF DREIMAL",
  "ПАМЯТКА ОХРАННИКУ БЦ «ГОРИЗОНТ»": "MERKBLATT WACHDIENST · BÜROZENTRUM HORIZON",
  "22:00 — запереть вход, лифт — в ночной режим (СТОП).": "22:00 — Eingang abschließen, Aufzug in den Nachtmodus (STOPP).",
  "Каждый час — осмотр по камерам. Замечания — в журнал (кнопка «Записать»).": "Jede Stunde — Kameras kontrollieren. Auffälliges ins Wachbuch (Taste „Eintragen“).",
  "Свет на пустых этажах — выключать с пульта.": "Licht auf leeren Etagen — am Pult ausschalten.",
  "Посторонних не впускать.": "Keine Unbefugten einlassen.",
  "Внутренний телефон — для связи с охраной соседних зданий.": "Haustelefon — für die Wachen der Nachbargebäude.",
  "(на обороте обложки, карандашом) Помехи на камере — не засматривайся. Запиши и переключи.": "(hinten im Umschlag, mit Bleistift) Rauschen auf einer Kamera — nicht hinstarren. Eintragen und umschalten.",
  "12.10  Лифт ночью ездит сам. Техник: «датчик».": "12.10  Der Aufzug fährt nachts von allein. Techniker: „Sensor“.",
  "15.10  Гаса зовут с 7-го. По имени. Голосом Марты. Марта три года как умерла.": "15.10  Jemand ruft Gus aus dem 7. Beim Namen. Mit Marthas Stimme. Martha ist seit drei Jahren tot.",
  "18.10  На пульте CAM 13. Такой камеры нет. Не смотри.": "18.10  Am Pult: CAM 13. So eine Kamera gibt es nicht. Schau nicht hin.",
  "20.10  НЕ ОТЗЫВАЙСЯ НА ИМЯ. НЕ ОТКРЫВАЙ ЕМУ ДВЕРЬ. САМ К НЕМУ НЕ ХОДИ — НИ НА СВЕТ, НИ В ЛИФТ.": "20.10  ANTWORTE NICHT AUF DEINEN NAMEN. MACH IHM NICHT AUF. GEH NICHT SELBST ZU IHM — NICHT INS LICHT, NICHT IN DEN AUFZUG.",
  "21.10  Мама позвала. Я ответил. Соль держит. Иду вниз.": "21.10  Mama rief. Ich antwortete. Das Salz hält. Gehe runter.",
  "Пульт пискнул: «ВХОД — ОТКРЫТ».": "Das Pult piepte: „EINGANG — OFFEN“.",
  "Камеры — внизу. Странное — «Записать». Свет, вход и лифт — на пульте.": "Kameras — unten. Seltsames — „Eintragen“. Licht, Eingang und Aufzug — am Pult.",
  "К 22:00 запереть вход и остановить лифт": "Bis 22 Uhr Eingang abschließen und Aufzug stoppen",
  "Ты как там? Не страшно одному? 😄": "Wie läuft's? Keine Angst so allein? 😄",
  "Нормально. Спи давай.": "Alles gut. Schlaf jetzt.",
  "Если честно — жутковато.": "Ehrlich? Ein bisschen gruselig.",
  "Держись! Утром позвоню": "Halt durch! Ich ruf morgen früh an",
  "«Итан?.. Это ты?»": "„Ethan?.. Bist du das?“",
  "— Да. Это я.": "— Ja. Ich bin's.",
  "Молча положить трубку": "Wortlos auflegen",
  "Рация. Канал уборщика": "Funk. Kanal des Putzmanns",
  "Сквозь шипение — голос Гаса.": "Durch das Rauschen — die Stimme von Gus.",
  "Не отвечать": "Nicht antworten",
  "«Итан… Спустись ко мне»": "„Ethan… Komm runter zu mir“",
