  "Постучать трижды": "Bussa tre volte",
  "За дверью зашлёпали мокрые шаги. А потом заплакала Катя.": "Dietro la porta risuonarono passi bagnati. Poi Katya si mise a piangere.",
  "ДЕРЖИ ДВЕРЬ": "TIENI LA PORTA",
  "Жми чаще. До шести он будет ломиться в дверь.": "Premi più in fretta. Fino alle sei sbatterà contro la porta.",
  "ТЫ ДОЖИЛ ДО УТРА": "HAI SUPERATO LA NOTTE",
  "Михалыч ушёл и не вернулся. Ты вернулся. А тот, у лифта, каждую ночь стоит чуть ближе.": "Mikhalych se n'è andato e non è più tornato. Tu sei tornato. E quello all'ascensore ogni notte è un po' più vicino.",
  "Звонит «Катя».": "Chiama «Katya».",
  "Ответить": "Rispondi",
  "Сбросить": "Rifiuta",
  "5. НЕ ИЩИ МИХАЛЫЧА": "5. NON CERCARE MIKHALYCH",
  "ПРАВИЛА СОБЛЮДЕНЫ": "REGOLE RISPETTATE",
  "Михалыч остался внизу. А правила теперь пишешь ты.": "Mikhalych è rimasto di sotto. E ora le regole le scrivi tu.",
  "ПРАВИЛО 1 НАРУШЕНО": "REGOLA 1 VIOLATA",
  "В 03:00 на седьмом включится свет. Не поднимайся.": "Alle 3:00 al settimo si accendono le luci. Non salire.",
  "ПРАВИЛО 2 НАРУШЕНО": "REGOLA 2 VIOLATA",
  "Если лифт приехал сам — не заходи.": "Se l'ascensore arriva da solo, non entrare.",
  "Я включил тринадцатую. Он уже смотрел в камеру. Ждал.": "Ho acceso la tredici. Guardava già nella telecamera. Aspettava.",
  "ПРАВИЛО 4 НАРУШЕНО": "REGOLA 4 VIOLATA",
  "Камеру 13 не включай.": "Non accendere la telecamera 13.",
  "ОНО ТЕБЯ УВИДЕЛО": "QUELLA COSA TI HA VISTO",
  "Если тринадцатая включилась сама — выдёргивай шнур.": "Se la tredici si accende da sola, stacca il cavo.",
  "ОНО УСЛЫШАЛО ТЕБЯ": "TI HA SENTITO",
  "Пока шаги рядом — не дыши.": "Finché i passi sono vicini, non respirare.",
  "ТЕМНОТА ДОГНАЛА": "IL BUIO TI HA RAGGIUNTO",
  "Не оглядывайся. Беги туда, где ещё светло.": "Non voltarti. Corri dove c'è ancora luce.",
  "ЗА ДВЕРЬЮ БЫЛО ОНО": "ERA DIETRO LA PORTA",
  "Он умеет звать. Стучать — нет.": "Sa chiamarti per nome. Bussare, no.",
  "ЗАСОВ НЕ ВЫДЕРЖАЛ": "IL CHIAVISTELLO HA CEDUTO",
  "Держи дверь до рассвета. Не сбавляй.": "Tieni la porta fino all'alba. Non rallentare.",
  "ТЫ ОТВЕТИЛ": "HAI RISPOSTO",
  "Ответить — значит впустить.": "Rispondere è farlo entrare.",
  "Пусто. Дождь стеной. На стекле чей-то отпечаток ладони?.. Нет, просто капли.": "Vuoto. Pioggia a dirotto. Un'impronta di mano sul vetro?… No, solo gocce.",
  "У лифта кто-то стоит?.. Нет. Показалось.": "Qualcuno all'ascensore?… No. Solo la mia immaginazione.",
  "Уборщик домывает седьмой. Хоть кто-то живой в этом здании.": "L'addetto alle pulizie finisce il settimo. Almeno qualcuno è vivo, qui dentro.",
