  "Удачи на первой смене! Не засни там :)": "In bocca al lupo per il primo turno! Non ti addormentare :)",
  "Сменщик протягивает связку. Рука дрожит.": "L'altra guardia porge il mazzo di chiavi. Gli trema la mano.",
  "«Как это — не сдал?»": "«Come, non ha passato le consegne?»",
