  "НЕ ОТЗЫВАЙСЯ НА ИМЯ.\nНЕ ОТКРЫВАЙ ЕМУ ДВЕРЬ.\nСАМ К НЕМУ НЕ ХОДИ —\nНИ НА СВЕТ, НИ В ЛИФТ.": "NON RISPONDERE AL TUO NOME.\nNON APRIRE LA PORTA A QUELLA COSA.\nNON ANDARCI TU STESSO —\nNÉ VERSO LA LUCE, NÉ IN ASCENSORE.",
  "МАМА ПОЗВАЛА. Я ОТВЕТИЛ.\nСОЛЬ ДЕРЖИТ. ИДУ ВНИЗ.": "HA CHIAMATO MAMMA. HO RISPOSTO.\nIL SALE TIENE. SCENDO.",
  "Тяни ползунок влево. Найди, где он ещё здесь.": "Trascina il cursore a sinistra: trova dove c'è ancora lui.",
