  "ДЕРЖИ ФРЭНКА": "TIENI FRANK",
  "Мать зовёт его из темноты. Не отпускай, пока голос не стихнет.": "Sua madre lo chiama dal buio. Non mollare finché la voce non si spegne.",
  "силы": "forza",
  "ДЕРЖАТЬ": "TIENI PREMUTO",
  "ДЕРЖУ": "TENGO",
  "Голос стих. Ненадолго.": "La voce si è spenta. Per ora.",
  "CAM 04  ЛЕСТНИЦА": "CAM 04  SCALE",
  "CAM 02  ХОЛЛ  03:00": "CAM 02  ATRIO  03:00",
  "РАССВЕТ": "ALBA",
  "Ты ни разу не ответил. Пока.": "Non hai mai risposto. Per ora.",
  "Звонит «Лили».": "Chiama «Lily».",
  "ТЫ НЕ СПУСТИЛСЯ": "NON SEI SCESO",
  "Ты дожил до утра. Фрэнк — нет.": "Sei arrivato al mattino. Frank no.",
  "ТЫ ПОСМОТРЕЛ ЕМУ В ЛИЦО": "L'HAI GUARDATO IN FACCIA",
  "Не смотри в тринадцатую камеру.": "Non guardare la telecamera tredici.",
  "ТЫ ПОШЁЛ НА СВЕТ": "SEI ANDATO VERSO LA LUCE",
  "Сам к нему не ходи — ни на свет, ни в лифт.": "Non andarci tu: né verso la luce, né in ascensore.",
  "ТЫ ОТОЗВАЛСЯ": "HAI RISPOSTO AL TUO NOME",
  "Гас не знал твоего имени. А оно знает.": "Gus non sapeva il tuo nome. Quella cosa sì.",
  "ОНО ОБЕРНУЛОСЬ": "QUELLA COSA SI È VOLTATA",
  "Тринадцатая включилась сама — выдёргивай шнур, не смотри.": "La tredici si è accesa da sola: stacca il cavo, non guardare.",
  "ОНО УСЛЫШАЛО": "QUELLA COSA TI HA SENTITO",
  "Оно ищет на звук. Пока шаги рядом — не дыши.": "Ti cerca dal suono. Finché i passi sono vicini, non respirare.",
  "Остановишься — догонит.": "Se ti fermi, ti raggiunge.",
  "ТЫ ПОШЁЛ НА ЗОВ": "HAI CEDUTO AL RICHIAMO",
  "Оно умеет звать. Стучать — нет.": "Sa chiamare. Bussare, no.",
  "ФРЭНК УШЁЛ НА ГОЛОС": "FRANK HA SEGUITO LA VOCE",
  "Держи его, пока голос не стихнет.": "Tienilo finché la voce non si spegne.",
  "Свои до утра подождут.": "I tuoi aspetteranno il mattino.",
  "ОБХОД": "RONDA",
  "СЕДЬМОЙ ЭТАЖ": "SETTIMO PIANO",
  "ТЫ ОТКРЫЛ ЕЙ": "L'HAI FATTA ENTRARE",
  "Лили спала в трёхстах километрах отсюда. Посторонних не впускать.": "Lily dormiva a trecento chilometri da qui. Non far entrare estranei.",
  "ОНО ПРИШЛО": "QUELLA COSA È ARRIVATA",
  "Три странности за час остались без внимания. Смотри камеры, записывай, выключай лишний свет.": "Tre anomalie in un'ora sono passate inosservate. Guarda le telecamere, annota, spegni le luci inutili.",
  "ТЫ ЗАСМОТРЕЛСЯ": "HAI FISSATO TROPPO A LUNGO",
  "Там, где помехи, кто-то стоит. Не смотри — запиши и переключи.": "Dove ci sono i disturbi, c'è qualcuno. Non guardare: annota e cambia.",
  "Внутренний": "Linea interna",
  "ТЫ НАЗВАЛСЯ": "TI SEI PRESENTATO",
  "Оно знает твоё имя. Ему нужно только, чтобы ты ответил.": "Quella cosa conosce il tuo nome. Vuole solo che tu risponda.",
