  "Пока ни одной записи.": "Nessuna annotazione.",
  "Фрэнк поднимается на голос. Не отпускай, пока голос не стихнет.": "Frank si alza verso la voce. Non mollare finché la voce non si spegne.",
  "Голос стих. Фрэнк сел на пол и закрыл лицо руками.": "La voce si spense. Frank si accasciò e si coprì il viso.",
