  "       Техник: «датчик».": "       Tecnico: «sensore».",
  "15.10  Гаса зовут с 7-го. По имени.": "15/10  Chiamano Gus dal 7. Per nome.",
  "       Голосом Марты.": "       Voce di Martha.",
