  "НЕ ЗОВИ МЕНЯ.": "NON CHIAMARMI.",
  "СТУЧИ ТРИ РАЗА": "BUSSA TRE VOLTE",
  "ПАМЯТКА ОХРАННИКУ БЦ «ГОРИЗОНТ»": "ISTRUZIONI PER LA GUARDIA · CENTRO D'AFFARI HORIZON",
  "22:00 — запереть вход, лифт — в ночной режим (СТОП).": "22:00 — chiudere l'ingresso, ascensore in modalità notte (STOP).",
  "Каждый час — осмотр по камерам. Замечания — в журнал (кнопка «Записать»).": "Ogni ora — controllo delle telecamere. Anomalie sul registro (pulsante «Annota»).",
  "Свет на пустых этажах — выключать с пульта.": "Luci dei piani vuoti: spegnere dalla console.",
  "Посторонних не впускать.": "Non far entrare estranei.",
  "Внутренний телефон — для связи с охраной соседних зданий.": "Il telefono interno serve per contattare la sicurezza degli edifici vicini.",
  "(на обороте обложки, карандашом) Помехи на камере — не засматривайся. Запиши и переключи.": "(sul retro della copertina, a matita) Disturbi su una telecamera: non fissarli. Annota e cambia.",
  "12.10  Лифт ночью ездит сам. Техник: «датчик».": "12/10  Di notte l'ascensore va da solo. Tecnico: «sensore».",
  "15.10  Гаса зовут с 7-го. По имени. Голосом Марты. Марта три года как умерла.": "15/10  Chiamano Gus dal 7. Per nome. Con la voce di Martha. Martha è morta tre anni fa.",
  "18.10  На пульте CAM 13. Такой камеры нет. Не смотри.": "18/10  CAM 13 sulla console. Quella telecamera non esiste. Non guardare.",
  "20.10  НЕ ОТЗЫВАЙСЯ НА ИМЯ. НЕ ОТКРЫВАЙ ЕМУ ДВЕРЬ. САМ К НЕМУ НЕ ХОДИ — НИ НА СВЕТ, НИ В ЛИФТ.": "20/10  NON RISPONDERE AL TUO NOME. NON APRIRE LA PORTA A QUELLA COSA. NON ANDARCI TU STESSO — NÉ VERSO LA LUCE, NÉ IN ASCENSORE.",
  "21.10  Мама позвала. Я ответил. Соль держит. Иду вниз.": "21/10  Mamma ha chiamato. Ho risposto. Il sale tiene. Scendo.",
  "Пульт пискнул: «ВХОД — ОТКРЫТ».": "La console ha emesso un bip: «INGRESSO — APERTO».",
  "Камеры — внизу. Странное — «Записать». Свет, вход и лифт — на пульте.": "Le telecamere sono in basso. Qualcosa di strano: «Annota». Luci, ingresso e ascensore: console.",
  "К 22:00 запереть вход и остановить лифт": "Entro le 22:00 chiudere l'ingresso e fermare l'ascensore",
  "Ты как там? Не страшно одному? 😄": "Come va? Non hai paura da solo? 😄",
  "Нормально. Спи давай.": "Tutto bene. Dormi, dai.",
  "Если честно — жутковато.": "Sinceramente? Un po' inquietante.",
  "Держись! Утром позвоню": "Tieni duro! Ti chiamo domattina",
  "«Итан?.. Это ты?»": "«Ethan?… Sei tu?»",
  "— Да. Это я.": "— Sì. Sono io.",
  "Молча положить трубку": "Riattacca senza parlare",
  "Рация. Канал уборщика": "Radio. Il canale delle pulizie",
  "Сквозь шипение — голос Гаса.": "Tra i fruscii, la voce di Gus.",
  "Не отвечать": "Non rispondere",
  "«Итан… Спустись ко мне»": "«Ethan… Scendi da me»",
  "— Гас! Держись, я сейчас поднимусь!": "— Gus! Resisti, sto salendo!",
  "Итан, я внизу у входа. Открой, пожалуйста, я промокла насквозь": "Ethan, sono giù all'ingresso. Apri, ti prego, sono fradicia",
  "Ты прячешься. Смотри камеры и записывай. Шаги у будки — «НЕ ДЫШИ».": "Ti nascondi. Guarda le telecamere e annota. Passi alla guardiola: «NON RESPIRARE».",
  "Шаги у самой будки. Держи кнопку, пока она не уйдёт.": "Passi proprio fuori dalla guardiola. Tieni premuto finché non se ne va.",
  "Она дышит за стеклом будки. Не отпускай.": "Respira dietro il vetro della guardiola. Non mollare.",
  "ЗАТАИТЬСЯ": "STAI FERMO",
  "НЕ ДЫШУ": "NON RESPIRO",
  "Шаги удаляются. Пока.": "I passi si allontanano. Per ora.",
  "Я на седьмом. Тут светло и тепло. Поднимись ко мне?": "Sono al settimo. Qui è luminoso e caldo. Vieni su da me?",
