  "Фрэнки, сынок, спустись ко мне. Я внизу": "Frankie, figliolo, scendi da me. Sono di sotto",
  "На зарядке. Номер не определён.": "In carica. Numero sconosciuto.",
  "Ответить: «Алло?»": "Rispondi: «Pronto?»",
  "(Дальше Фрэнк писал от руки — в журнале на столе. Журнал перевязан бечёвкой, на обложке: «До трёх. Весь.»)": "(Il resto Frank lo scrisse a mano, nel registro sul tavolo. È legato con lo spago; sulla copertina: «Prima delle tre. Tutto.»)",
