  "В будку, под стойку": "Kulübeye, masanın altına",
  "К аварийному выходу": "Acil çıkışa",
  "Ты чего не отвечаешь? Перезвони.": "Neden cevap vermiyorsun? Geri ara.",
  "НЕ ДЫШИ": "NEFES ALMA",
  "Держи кнопку, пока шаги не уйдут. Отпустишь раньше — услышит.": "Ayak sesleri gidene kadar düğmeyi basılı tut. Erken bırakırsan o şey seni duyar.",
