  "ТЫ ВЫБРАЛСЯ": "DIŞARI ÇIKTIN",
  "Ей правил никто не давал.": "Ona kuralları kimse söylememişti.",
  "«ПОМОГИ. МИНУС 2.\nСТУЧИ ТРИЖДЫ»": "“YARDIM. EKSİ 2.\nKAPIYI ÜÇ KEZ ÇAL”",
  "Минус второй. Стучать трижды.": "Eksi iki. Kapıyı üç kez çal.",
