  "За дверью зашлёпали мокрые шаги. А потом заплакала Катя.": "Kapının ardında ıslak ayak sesleri şapırdadı. Sonra Katya ağlamaya başladı.",
  "ДЕРЖИ ДВЕРЬ": "KAPIYI TUT",
  "Жми чаще. До шести он будет ломиться в дверь.": "Daha hızlı dokun. Altıya kadar kapıya çarpıp duracak.",
  "ТЫ ДОЖИЛ ДО УТРА": "GECEYİ ATLATTIN",
  "Михалыч ушёл и не вернулся. Ты вернулся. А тот, у лифта, каждую ночь стоит чуть ближе.": "Mikhalych gitti ve bir daha dönmedi. Sen döndün. Asansörün yanındaki ise her gece biraz daha yakında duruyor.",
  "Звонит «Катя».": "“Katya” arıyor.",
