  "Если тринадцатая включилась сама — выдёргивай шнур.": "On üç kendi kendine açılırsa kabloyu çek.",
  "ОНО УСЛЫШАЛО ТЕБЯ": "O SENİ DUYDU",
  "Пока шаги рядом — не дыши.": "Ayak sesleri yakındayken nefes alma.",
