  "Он умеет звать. Стучать — нет.": "O, adınla seslenebilir. Kapıyı çalamaz.",
  "ЗАСОВ НЕ ВЫДЕРЖАЛ": "SÜRGÜ DAYANAMADI",
  "Держи дверь до рассвета. Не сбавляй.": "Kapıyı şafağa kadar tut. Yavaşlama.",
  "ТЫ ОТВЕТИЛ": "CEVAP VERDİN",
  "Ответить — значит впустить.": "Cevap vermek, onu içeri almaktır.",
  "Пусто. Дождь стеной. На стекле чей-то отпечаток ладони?.. Нет, просто капли.": "Boş. Sağanak yağmur. Camda bir el izi mi?.. Hayır, sadece yağmur damlaları.",
  "У лифта кто-то стоит?.. Нет. Показалось.": "Asansörün yanında biri mi?.. Hayır. Hayal görmüşüm.",
