  "БУБЛИК": "BİSKÜVİ",
  "03.10  Обход. Лампа на 4-м мигает.": "03.10  Devriye. 4. kat lambası titriyor.",
  "05.10  Обход. Кошка у баков.": "05.10  Devriye. Konteynerin yanında kedi.",
