  "Не спится :( Как первая смена? Позвони утром": "Nie mogę spać :( Jak pierwsza zmiana? Zadzwoń rano",
  "минуту назад": "minutę temu",
  "«Итан, открой!»": "„Ethan, otwórz!”",
  "Открыть": "Otworzyć",
  "Написать на стекле": "Napisać na szybie",
  "Оно повторяет твоё имя.": "To powtarza twoje imię.",
  "Спрятаться в будке": "Ukryć się w budce",
  "Бежать к аварийному выходу": "Biec do wyjścia awaryjnego",
  "Оно ищет на звук. Держи палец, пока шаги рядом.": "To szuka po dźwięku. Trzymaj palec, dopóki kroki są blisko.",
  "ВНУТРИ": "W ŚRODKU",
  "«Ты со мной», — сказал ты ей. И не соврал.": "„Jesteś ze mną” — powiedziałeś jej. I nie skłamałeś.",
  "СЕСТРА": "SIOSTRA",
  "Оно пошло туда, где его ещё не ждут. Твоим голосом.": "Poszło tam, gdzie nikt się go jeszcze nie spodziewa. Twoim głosem.",
  "CAM −2  СЕРВЕРНАЯ": "CAM −2  SERWEROWNIA",
  "CAM −2  ПОДВАЛ": "CAM −2  PIWNICA",
  "НЕ ЗОВИ МЕНЯ.\nСТУЧИ ТРИ РАЗА.": "NIE WOŁAJ MNIE.\nPUKAJ TRZY RAZY.",
  "Фрэнк жив. Он внизу.": "Frank żyje. Jest na dole.",
  "Спуститься к нему": "Zejść do niego",
  "ПОДВАЛ": "PIWNICA",
  "Темно. Веди фонарём, найди дверь серверной.": "Ciemno. Poświeć latarką i znajdź drzwi serwerowni.",
  "Железная дверь. Под ней — свет.": "Żelazne drzwi. Pod nimi — światło.",
  "«Заходи, сынок. Открыто».": "„Wchodź, synu. Otwarte.”",
