  "Сам к нему не ходи — ни на свет, ни в лифт.": "Sam do niego nie chodź — ani do światła, ani do windy.",
  "ТЫ ОТОЗВАЛСЯ": "ODEZWAŁEŚ SIĘ",
  "Гас не знал твоего имени. А оно знает.": "Gus nie znał twojego imienia. A to zna.",
