  "Тринадцатая включилась сама — выдёргивай шнур, не смотри.": "Trzynastka włączyła się sama — wyrwij kabel, nie patrz.",
  "ОНО УСЛЫШАЛО": "TO USŁYSZAŁO",
  "Оно ищет на звук. Пока шаги рядом — не дыши.": "To szuka po dźwięku. Dopóki kroki są blisko — nie oddychaj.",
