  "Оно умеет звать. Стучать — нет.": "To umie wołać. Pukać — nie.",
  "ФРЭНК УШЁЛ НА ГОЛОС": "FRANK POSZEDŁ ZA GŁOSEM",
  "Держи его, пока голос не стихнет.": "Trzymaj go, dopóki głos nie ucichnie.",
  "Свои до утра подождут.": "Swoi poczekają do rana.",
