  "Лили спала в трёхстах километрах отсюда. Посторонних не впускать.": "Lily spała trzysta kilometrów stąd. Osób postronnych nie wpuszczać.",
  "ОНО ПРИШЛО": "TO PRZYSZŁO",
  "Три странности за час остались без внимания. Смотри камеры, записывай, выключай лишний свет.": "Trzy anomalie w ciągu godziny zostały niezauważone. Patrz na kamery, zapisuj, gaś zbędne światło.",
