  "22:00 — запереть вход, лифт — в ночной режим (СТОП).": "22:00 — zamknąć wejście, przełączyć windę w tryb nocny (STOP).",
  "Каждый час — осмотр по камерам. Замечания — в журнал (кнопка «Записать»).": "Co godzinę — przegląd kamer. Uwagi do dziennika (przycisk „Zapisz”).",
